    this.context.method = 'checkConfiguration';

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'mssql.host', value: this.host },
      { key: 'mssql.database', value: this.database },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    // Check the conditional logic for authentication
    const hasUsernameAndPassword = this.username && this.password;
    const hasManagedIdentity =
      this.useManagedIdentity && this.managedIdentityClientId;

    if (!hasUsernameAndPassword && !hasManagedIdentity) {
      this.customLogger.error(
        'Either username/password or managedIdentityClientId/useManagedIdentity must be provided',
        this.context,
      );
      throw new Error(
        'Configuration error: You must set either username/password or managedIdentityClientId/useManagedIdentity',
      );
    }
  }
}

