import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class TelemetryConfigService implements OnModuleInit {
  private readonly context: JobsLogContext = {
    method: '',
    service: TelemetryConfigService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get enableTelemetry(): boolean {
    return this.configService.get<string>('enableTelemetry') === 'true';
  }

  public get enableRedisInstrumentation(): boolean {
    return (
      this.configService.get<string>('enableRedisInstrumentation') === 'true'
    );
  }

  public get enableMetrics(): boolean {
    return this.configService.get<string>('enableMetrics') === 'true';
  }

  public get enableLiveMetrics(): boolean {
    return this.configService.get<string>('enableLiveMetrics') === 'true';
  }

  public get enablePerformanceCounters(): boolean {
    return (
      this.configService.get<string>('enablePerformanceCounters') === 'true'
    );
  }

  public get connectionString(): string | undefined {
    return this.configService.get<string>(
      'applicationInsightsConnectionString',
    );
  }

  public get serviceName(): string {
    return this.configService.get<string>('serviceName') ?? '';
  }

  public get samplingRatio(): number | undefined {
    const value = this.configService.get<string>('telemetrySamplingRatio');
    return value === undefined ? undefined : Number(value);
  }

  public get hostName(): string | undefined {
    return this.configService.get<string>('hostname') ?? os.hostname();
  }

  public async onModuleInit(): Promise<void> {
    await this.validateConfiguration();
  }

  /* =======================
   * Validation (read-only, no initialization)
   * ======================= */

  private async validateConfiguration(): Promise<void> {
    this.context.method = 'validateConfiguration';

    if (!(await this.appConfigService.reachable())) {
      const message = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;
      this.customLogger.error(message, this.context);
      throw new Error(message);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'enableTelemetry',
        value: this.enableTelemetry,
      },
      {
        key: 'enableRedisInstrumentation',
        value: this.enableRedisInstrumentation,
      },
      {
        key: 'applicationInsightsConnectionString',
        value: this.enableTelemetry ? this.connectionString : true, // Skip when telemetry disabled
      },
      {
        key: 'serviceName',
        value: this.serviceName,
      },
      {
        key: 'samplingRatio',
        value: this.samplingRatio,
      },
      {
        key: 'hostName',
        value: this.hostName,
      },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required Telemetry configurations are properly set',
      this.context,
    );
  }
}

import { telemetryMetrics, PROCESSING_STATUS } from '@mesx/common-lib';
import { Controller, Post, Req } from '@nestjs/common';
import { Request } from 'express';
import { AppLogger } from '@/common/logger/app-logger';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { DaprService } from '@/dapr/dapr.service';

// Environment variables
const bindings = {
  bindingConfigServer:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_CONFIG_SERVER_SHP_DI,
  bindingCustomer: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_CUST,
  bindingOutboundDel: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_OUTBD_DEL,
  bindingOutboundDelDtl:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_OUTBD_DEL_DTL,
  bindingTpaAssignment:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_TPA_ASSIGNMENT,
  bindingTpaCode: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_TPA_CODE,
  topicPlants: process.env.TOPIC_PLANTS,
};

@Controller('')
export class DaprController {
  public constructor(
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic Entity name for telemetry
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const event = request.body;
    const plantCode = event?.S_SITE || event?.PLANT;

    const startTime = Date.now();

    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      const result = await this.daprService.handleMessage(event);
      if (result.processed) {
        const duration = Date.now() - startTime;
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
      }
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.bindingConfigServer)
  public async receiveEventTConfigServer(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventConfigServer',
      'config-server',
    );
  }

  @Post(bindings.bindingCustomer)
  public async receiveEventCustomer(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventCustomer',
      'customer',
    );
  }

  @Post(bindings.bindingOutboundDel)
  public async receiveEventOutboundDel(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventOutboundDel',
      'outbound-delivery',
    );
  }

  @Post(bindings.bindingOutboundDelDtl)
  public async receiveEventOutboundDelDtl(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventOutboundDelDtl',
      'outbound-delivery-dtl',
    );
  }

  @Post(bindings.bindingTpaAssignment)
  public async receiveEventTpaAssignment(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventTpaAssignment',
      'tpa-assignment',
    );
  }

  @Post(bindings.bindingTpaCode)
  public async receiveEventTpaCode(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventTpaCode',
      'tpa-code',
    );
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

