import { appendAndSaveToCacheQueue } from '@/helpers/queues/append-and-save-to-cache-queue';
import { loadQueuesFromFileShare } from '@/helpers/queues/load-queues-from-file-share';
import { moveToDeadLetterQueue } from '@/helpers/queues/move-to-dead-letter-queue';
import { removeMessageQueue } from '@/helpers/queues/remove-message-queue';
import { beforeApplicationShutdown } from '@/helpers/shutdown/before-application-shutdown';
import {
  decrementPendingMessageCount,
  incrementPendingMessageCount,
} from '@/helpers/statistics/pending-message-stats';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';
import { validateAndTrackChanges } from '@/helpers/validations/validate-and-track-data-changes';
import { IngestionEventTrackingService } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.service';
import { OutboundDeliveryService } from '@/modules/outbound-delivery/outbound-delivery.service';

@Injectable()
export class DaprService implements OnModuleInit, BeforeApplicationShutdown {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprService.name, userId };
  }

  private readonly serviceMutexes: Record<string, Mutex> = {};

  private processingQueue: Record<string, boolean> = {
    customerDef: false,
    outboundDelivery: false,
    outboundDeliveryDtl: false,
    plantConfig: false,
    tpaAssignment: false,
    tpaCode: false,
  };

  private readonly daprClient: DaprClient;

  public plantList: Array<PlantsResponseDto> = [];

  private readonly inMemoryQueue: {
    customerDef: Array<RedisMessage>;
    outboundDelivery: Array<RedisMessage>;
    outboundDeliveryDtl: Array<RedisMessage>;
    plantConfig: Array<RedisMessage>;
    tpaAssignment: Array<RedisMessage>;
    tpaCode: Array<RedisMessage>;
  } = {
    customerDef: [],
    outboundDelivery: [],
    outboundDeliveryDtl: [],
    plantConfig: [],
    tpaAssignment: [],
    tpaCode: [],
  };

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly redisConfigService: RedisConfigService,
    private readonly daprConfigService: DaprConfigService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly eventhubService: EventhubService,
    private readonly fileShareConfigService: FileShareConfigService,
    private readonly outboundService: OutboundDeliveryService,
  ) {
    this.daprClient = new DaprClient();
    this.serviceMutexes.outboundDelivery = new Mutex();
    this.serviceMutexes.outboundDeliveryDtl = new Mutex();
    this.serviceMutexes.tpaCode = new Mutex();
    this.serviceMutexes.tpaAssignment = new Mutex();
    this.serviceMutexes.customerDef = new Mutex();
    this.serviceMutexes.plantConfig = new Mutex();
  }

  /**
   * Handles tasks that need to be performed before the application shuts down.
   * @param signal - The signal that triggered the shutdown.
   * @returns A promise that resolves when the shutdown tasks are complete.
   */
  public async beforeApplicationShutdown(signal: string): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'ship-di';
    await beforeApplicationShutdown(
      this.customLogger,
      this.inMemoryQueue,
      queueBackupBasePath,
      microServiceName,
      signal,
    );
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
    await this.initializeQueues();
  }

  public async initializePlant(): Promise<void> {
    const context = DaprService.createLogContext('initializePlant');

    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStoreAmr,
        this.redisConfigService.redisPlantKey,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  private checkAndProcessQueues(): void {
    const context = DaprService.createLogContext('checkAndProcessQueues');
    for (const [queueName, queueData] of Object.entries(this.inMemoryQueue)) {
      if (queueData && queueData.length > 0) {
        if (this.processingQueue[queueName]) {
          this.customLogger.verbose(
            `Queue ${queueName} is already being processed, skipping.`,
            context,
          );
        } else {
          this.processMessageQueue(queueName);
        }
      } else {
        this.customLogger.verbose(
          `Queue ${queueName} is empty, skipping processing.`,
          context,
        );
      }
    }
  }

  private async initializeQueues(): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'ship-di';
    await loadQueuesFromFileShare(
      this.customLogger,
      queueBackupBasePath,
      microServiceName,
      this.inMemoryQueue,
    );
    this.checkAndProcessQueues();
  }

  /**
   * Updates data without using the cache if no result is found in Redis.
   * Emits an event after confirming whether the data exists or not.
   * @param keysValueArray - key values array
   * @param mappedData - The data that has been mapped and needs to be processed.
   * @param operation - The operation to be performed (e.g., "create", "update").
   * @param source - The source identifier from which the data is retrieved.
   * @param destination - The destination identifier to which the data will be sent.
   * @returns A Promise that resolves to a boolean indicating whether the event was emitted (true) or not (false).
   */
  private async updateDataWithoutCache(
    keysValueArray: KeysValueArray,
    mappedData: MappedOutput,
    operation: string,
    source: string,
    destination: string,
  ): Promise<boolean> {
    const context = DaprService.createLogContext(
      'updateDataWithoutCache',
      Number(mappedData?.plant),
    );
    const resultOutbound = await this.outboundService.findOutbound(
      keysValueArray,
      source,
    );
    this.customLogger.debug(
      `Received from find Outbound - result: ${JSON.stringify(resultOutbound)} - result: ${JSON.stringify(resultOutbound)}`,
      context,
    );
    if (resultOutbound) {
      const data = {
        ...mappedData,
      };

      await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destination,
        data,
        operation,
      );
      return true;
    }
    return false;
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   * @param redisStoreAmr Redis Store AMR
   */
  private async processMessage(
    message: RedisMessage,
    redisStoreAmr: string,
  ): Promise<void> {
    const {
      mappedData,
      keysValue,
      destination,
      ingestionEventTracking,
      sourceTable,
      operation,
      keysValueArray,
      cacheTreatment,
    } = message;
    const context = DaprService.createLogContext(
      'processMessage',
      Number(mappedData?.plant),
    );
    try {
      const operationInfo = {
        name: '',
        srcLocation: 'processMessage',
      };

      if (!operation || !keysValueArray) {
        return;
      }
      if (operation !== 'r' && ingestionEventTracking) {
        const validateAndTrackIngestionEventTracking: boolean =
          await validateAndTrackChanges(
            this.customLogger,
            this.ingestionEventTrackingService,
            ingestionEventTracking,
          );
        if (!validateAndTrackIngestionEventTracking) {
          return;
        }
        await this.ingestionEventTrackingService.upsertCache(
          ingestionEventTracking,
        );
      }
      if (cacheTreatment) {
        const cacheKey = `${keysValue}.${operation}`;
        const operationDetails = {
          cacheKey,
        };
        // Process the event (you may want to implement this)
        this.customLogger.debug(`Checking state key: ${cacheKey}`, context);
        operationInfo.name = 'Get state';
        const result = await execAndLog(
          this.customLogger,
          context,
          () => this.daprClient.state.get(redisStoreAmr, cacheKey),
          operationInfo,
          operationDetails,
        );
        // Update data without using cache if there's no result from Redis,
        //  And after confirming whether the data is inserted or not.
        if (!result.valueOf() && operation === 'u') {
          const dataUpdated = await this.updateDataWithoutCache(
            keysValueArray,
            mappedData,
            operation,
            sourceTable,
            destination,
          );
          if (dataUpdated) {
            return;
          }
        }

        // Caching the first wave of data
        if (
          !result.valueOf() ||
          Object.values(result.valueOf())[0].sourceTable === sourceTable
        ) {
          if (!sourceTable) {
            return;
          }
          const recordCache = {
            destination,
            keysValue,
            mappedData,
            sourceTable,
          };
          await appendAndSaveToCache(
            this.customLogger,
            this.daprClient,
            this.redisConfigService.redisStoreAmr,
            cacheKey,
            result,
            recordCache,
          );
          return;
        }

        const redisData = Object.values(result.valueOf()).at(-1).mappedData;
        const destinationRedis = Object.values(result.valueOf()).at(
          -1,
        ).destination;
        const destinationService = destinationRedis + destination;
        const completedData = { ...redisData, ...mappedData }; // Append the data
        operationInfo.name = 'Delete state';
        await execAndLog(
          this.customLogger,
          context,
          async () => {
            // We processed the last records => Cache can be freed
            this.customLogger.debug(`Deleting state key: ${cacheKey}`, context);
            return this.daprClient.state.delete(redisStoreAmr, cacheKey);
          },
          operationInfo,
          operationDetails,
        );
        if (!operation) return;
        await emitSqlEvent(
          this.customLogger,
          context,
          this.eventEmitter,
          destinationService,
          completedData,
          operation,
        );
      } else {
        await emitSqlEvent(
          this.customLogger,
          context,
          this.eventEmitter,
          destination,
          mappedData,
          operation,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Process message in the queue
   * @param queueKey - Queue
   * @returns void
   */
  private async processNextMessage(queueKey: string): Promise<void> {
    const context = DaprService.createLogContext('processNextMessage');
    try {
      const messageQueue =
        this.inMemoryQueue[queueKey as keyof typeof this.inMemoryQueue];
      // Exit if the queue is empty
      if (messageQueue.length === 0) {
        this.customLogger.verbose(
          `No messages left in queue ${queueKey}.`,
          context,
        );
        return; // Exit when there are no more messages to process
      }

      // Process the first message in the queue
      const message = messageQueue[0];
      if (message) {
        try {
          this.customLogger.debug(
            `Processing message: ${JSON.stringify(message)} for ${queueKey}`,
            context,
          );

          // Process the message
          await this.processMessage(
            message,
            this.redisConfigService.redisStoreAmr,
          );

          this.customLogger.verbose(
            `Message processed for ${queueKey}, removing from queue.`,
            context,
          );

          // Remove the processed message
          await removeMessageQueue(
            this.customLogger,
            this.serviceMutexes,
            this.daprClient,
            {
              inMemoryQueue: this.inMemoryQueue,
              processingQueue: this.processingQueue,
              queueKey,
              redisStoreNameAmr: this.redisConfigService.redisStoreAmr,
            },
            message,
          );
        } catch (error) {
          this.customLogger.error(
            `Error processing message for ${queueKey}: ${error.message}`,
            context,
            error.stack,
          );
          await moveToDeadLetterQueue(
            this.customLogger,
            context,
            this.redisConfigService.redisStoreAmr,
            this.daprClient,
            queueKey,
            message,
            MESSAGE_ACTION.ERROR,
          ); // Move to DLQ if error occurs
        }

        // Continue processing the next message
        await this.processNextMessage(queueKey); // Recursive call to process the next message
      }
    } catch (error) {
      this.customLogger.error(
        `Error retrieving Redis queue for ${queueKey}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  /**
   * Process Message Queue Sequentially using Recursion
   * @param queueKey Queue Key
   */
  private async processMessageQueue(queueKey: string): Promise<void> {
    const context = DaprService.createLogContext('processMessageQueue');

    try {
      // Mark processing as ongoing for this queue
      this.processingQueue[queueKey] = true;
      // Start processing with the recursive function
      await this.processNextMessage(queueKey);
    } finally {
      // Reset the processing flag to indicate processing is complete
      this.processingQueue[queueKey] = false;
      this.customLogger.verbose(
        `Finished processing queue for ${queueKey}.`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @returns Start the dapr server
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
  ): Promise<{ processed: boolean; reason?: string }> {
    const context = DaprService.createLogContext('handleMessage');

    incrementPendingMessageCount();
    try {
      if (!checkPayloadConsistency(this.customLogger, context, record))
        return { processed: false, reason: 'Payload consistency check failed' };

      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable)
        return { processed: false, reason: 'Missing sourceTable' };
      if (!operation) {
        return { processed: false, reason: 'Missing operation' };
      }

      const destination = this.mappingService.getDestinationTable(sourceTable);
      const queueKey = destination;

      await appendAndSaveToCacheQueue(
        this.customLogger,
        this.daprClient,
        this.redisConfigService.redisStoreAmr,
        {
          mappingService: this.mappingService,
          serviceMutexes: this.serviceMutexes,
        },
        this.inMemoryQueue,
        this.processingQueue,
        this.plantList,
        {
          key: queueKey,
          operation,
          record,
          sourceTable,
        },
      );
      if (this.processingQueue[queueKey]) {
        this.customLogger.debug(
          `message ${queueKey}is already processing`,
          context,
        );
        return {
          processed: false,
          reason: `message ${queueKey} is already in processing`,
        };
      }
      this.customLogger.debug(
        `Starting message queue ${queueKey} processing`,
        context,
      );
      this.processMessageQueue(queueKey);
      return { processed: true };
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
      return { processed: false, reason: 'error' };
    } finally {
      if (record) {
        await execAndLog(this.customLogger, context, async () => {}, {
          name: 'handleMessage function runtime',
          srcLocation: 'handleMessage',
        });
      }
      decrementPendingMessageCount();
    }
  }
}

import { TpaAssignmentDto } from './tpa-assignment.dto';
import { OutboundDeliveryDTLDto } from '@/dapr/dtos/outbd-del-dtl.dto';
import { OutboundDeliveryDto } from '@/dapr/dtos/outbd-del.dto';
import { TpaCodeDto } from '@/dapr/dtos/tpa-code.dto';

type CombinedDto =
  | OutboundDeliveryDto
  | OutboundDeliveryDTLDto
  | TpaCodeDto
  | TpaAssignmentDto;

interface CombinedDtoWithIndexSignature {
  [key: string]: number | string | boolean | undefined;
}

export type CombinedDtoWithIndex = CombinedDto & CombinedDtoWithIndexSignature;

export class CommonDto {
  public __op?: string;

  public __ts_ms?: number;

  public __source_ts_ms?: number;

  public __source_db?: string;

  public __source_schema?: string;

  public __source_table?: string;

  public __source_change_lsn?: string;

  public __source_commit_lsn?: string;

  public __deleted?: string;

  public ___gtw?: string;
}

import { CommonDto } from '@/dapr/dtos/common.dto';

export class OutboundDeliveryDTLDto extends CommonDto {
  public OUTBOUNDDELIVERY: string;

  public PLANT: number;
}

import { CommonDto } from '@/dapr/dtos/common.dto';

export class OutboundDeliveryDto extends CommonDto {
  public OUTBOUNDDELIVERY: string;

  public TPA_CODE: string;

