    logger.debug('Initialize Plant List', context);
    const redisData = await daprClient.state.get(redisStoreAmr, redisPlantKey);
    let plantList: Array<PlantsResponseDto>;

    if (redisData.valueOf()) {
      // Get plant list from Redis
      [plantList] = Object.values(redisData.valueOf());
