      `Error Getting list Plant : ${error.message}`,
      context,
      error.stack,
    );
    throw new HttpException(
      `error in Getting list Plant ${error}`,
      HttpStatus.BAD_REQUEST,
    );
  }
}

import { Logger } from '@nestjs/common';

/**
 *
 * @param dateString {string} dateString - The date string in ISO format that needs to be converted to UTC.
 * @returns string | undefined
 */
export function convertToUtc(dateString: string | null): string | undefined {
  if (!dateString) {
    Logger.error('dateString is null or undefined');
    return undefined; // Return early if dateString is null
  }

  try {
    // Create a new Date object from the date string
    const localDate = new Date(dateString);

    // Convert to UTC using the timezone offset
    const utcDate = new Date(
      localDate.getTime() + localDate.getTimezoneOffset() * 60_000,
    );

    // Format to ISO string
    return utcDate.toISOString();
  } catch (error) {
    Logger.error(`Error converting date to UTC: ${error.message}`);
    return undefined;
  }
}

