import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Customer } from './customer.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class CustomerService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: CustomerService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(Customer)
    private readonly customerRepository: Repository<Customer>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('customerDef.c')
  private async create(payload: Customer): Promise<void> {
    const context = CustomerService.createLogContext('create');
    if (!payload) {
      this.customLogger.error(`Payload is empty ${payload}`, context);
      return;
    }
    const startTime = Date.now();
    try {
      const { ...customerData } = payload;

      await this.customerRepository.upsert(
        { ...customerData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['customerCode', 'sapServer'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.customerCode),
        'customer',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.customerCode),
        'customer',
      );
    } catch (error) {
      this.customLogger.error(
        `Error inserting customer and publishing message: ${error.message}`,
        context,
      );
    }
  }

  @OnEvent('customerDef.u')
  private async updateByCustomer(payload: Customer): Promise<void> {
    const context = CustomerService.createLogContext('updateByCustomer');
    const { customerCode, sapServer, ...customerData } = payload;
    if (!customerCode || !sapServer) {
      this.customLogger.error(
        `Invalid payload: missing customerCode or sapServer`,
        context,
      );
      return;
    }

    const startTime = Date.now();
    try {
      await this.customerRepository.upsert(
        {
          customerCode,
          sapServer,
          ...customerData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['customerCode', 'sapServer'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(customerCode),
        'customer',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(customerCode),
        'customer',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating customer: ${error.message}`,
        context,
      );
    }
  }

  @OnEvent('customerDef.r')
  private async readSnapshot(payload: Customer): Promise<void> {
    const context = CustomerService.createLogContext('readSnapshot');

    if (!payload) {
      this.customLogger.error(`Payload is empty ${payload}`, context);
      return;
    }

    const startTime = Date.now();
    try {
      const { customerCode, sapServer, ...customerData } = payload;
      await this.customerRepository.upsert(
        {
          customerCode,
          sapServer,
          ...customerData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['customerCode', 'sapServer'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(customerCode),
        'customer',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(customerCode),
        'customer',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating customer: ${error.message}`,
        context,
      );
    }
  }
}

