@Injectable()
export class OutboundDeliveryService {
  private static createLogContext(
    method: string,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      service: OutboundDeliveryService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(OutboundDelivery)
    private readonly outboundRepository: Repository<OutboundDelivery>,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
    private readonly customLogger: AppLogger,
  ) {}

  public async findOutbound(
    payload: KeysValueArray,
    source: string,
  ): Promise<OutboundDelivery | undefined> {
    const context = OutboundDeliveryService.createLogContext('findOutbound');
    const startTime = Date.now();
    try {
      this.customLogger.debug(
        `entring find Outbound payload:${JSON.stringify(payload)} source:${source}`,
        context,
      );
      if (source === 'OUTBD_DEL_DTL') {
        const { outbound, plant, sapServer } = payload;

        const outboundResults = await this.outboundRepository
          .createQueryBuilder('outbound_delivery')
          .select(['outbound_delivery.outbound AS outbound'])
          .where('outbound_delivery.plant = :plant', { plant })
          .andWhere('outbound_delivery.outbound = :outbound', {
            outbound,
          })
          .andWhere('outbound_delivery.sap_server=:sapServer', {
            sapServer,
          })
          .getRawOne();
        const result = outboundResults;
        const sqlDuration = Date.now() - startTime;
        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          String(plant),
          'outbound-delivery',
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.SQL,
          String(plant),
          'outbound-delivery',
        );
        return result;
      }
      if (source === 'OUTBD_DEL') {
        const { outbound, sapServer } = payload;
        const outboundResults = await this.outboundRepository
          .createQueryBuilder('outbound_delivery')
          .select(['outbound_delivery.outbound AS outbound'])
          .where('outbound_delivery.sap_server = :sapServer', {
            sapServer,
          })
          .andWhere('outbound_delivery.outbound = :outbound', {
            outbound,
          })
          .getRawOne();
        const result = outboundResults;
        const sqlDuration = Date.now() - startTime;
        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          String(sapServer),
          'outbound-delivery',
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.SQL,
          String(sapServer),
          'outbound-delivery',
        );
        return result;
      }
      return undefined;
    } catch (error) {
      this.customLogger.error(
        `error in find in data base: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('outboundDelivery.c')
  private async create(payload: OutboundDelivery): Promise<void> {
    const context = OutboundDeliveryService.createLogContext('create');
    if (!payload)
      return this.customLogger.error(`Payload is empty: ${payload}`, context);

    const startTime = Date.now();
    try {
      const { ...outboundDeliveryData } = payload;
      this.customLogger.debug(
        `Storing incomplete outboundDelivery in Redis with data ${JSON.stringify(outboundDeliveryData)}`,
        context,
      );
      await this.outboundRepository.upsert(
        { ...outboundDeliveryData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['outbound', 'sapServer'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.outbound),
        'outbound-delivery',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.outbound),
        'outbound-delivery',
      );
    } catch (error) {
      this.customLogger.error(
        `Error in creating outboundDelivery: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('outboundDelivery.u')
  private async updateByOutboundAndPlant(
    payload: OutboundDelivery,
  ): Promise<void> {
    const context = OutboundDeliveryService.createLogContext(
      'updateByOutboundAndPlant',
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    const startTime = Date.now();
    try {
      const { outbound, sapServer, ...odData } = payload;

      await this.outboundRepository.upsert(
        { outbound, sapServer, ...odData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['outbound', 'sapServer'] },
      );

      const response = await this.outboundRepository
        .createQueryBuilder('od')
        .innerJoinAndSelect(
          'OutboundDeliveryDtl',
          'odDtl',
          'od.outbound = odDtl.outbound AND od.sapServer = odDtl.sapServer',
        )
        .where('od.outbound = :outbound AND od.sapServer = :sapServer', {
          outbound,
          sapServer,
        })
        .select(['odDtl.plant AS plant'])
        .getRawOne();
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(outbound),
        'outbound-delivery',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(outbound),
        'outbound-delivery',
      );
      if (response) {
        const outboundMessage: OutboundMessage = {
          outbound,
          plant: response.plant,
        };

        await this.publishMessageService.publishMessage(
          this.eventhubService.topicOutbound,
          outboundMessage,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating outbound: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('outboundDelivery.r')
  private async readSnapshot(payload: OutboundDelivery): Promise<void> {
    const context =
      OutboundDeliveryService.createLogContext('outboundDelivery');
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    const startTime = Date.now();
    try {
      const { outbound, sapServer, ...odData } = payload;

      await this.outboundRepository.upsert(
        { outbound, sapServer, ...odData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['outbound', 'sapServer'] },
      );

      const response = await this.outboundRepository
        .createQueryBuilder('od')
        .innerJoinAndSelect(
          'OutboundDeliveryDtl',
          'odDtl',
          'od.outbound = odDtl.outbound AND od.sapServer = odDtl.sapServer',
        )
        .where('od.outbound = :outbound  and od.sapServer = :sapServer', {
          outbound,
          sapServer,
        })
        .select(['odDtl.plant AS plant'])
        .getRawOne();
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(outbound),
        'outbound-delivery',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(outbound),
        'outbound-delivery',
      );
      if (response) {
        const outboundMessage: OutboundMessage = {
          outbound,
          plant: response.plant,
        };

        await this.publishMessageService.publishMessage(
          this.eventhubService.topicOutbound,
          outboundMessage,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error upserting Outbound Delivery with keys ${JSON.stringify(payload)} Error Messsage :  ${error}`,
        context,
      );
    }
    return undefined;
  }

  private convertToUtc(dateString: string | null): string | undefined {
    const context = OutboundDeliveryService.createLogContext('convertToUtc');
    if (!dateString) {
      this.customLogger.error('dateString is null or undefined', context);
      return undefined; // Return early if dateString is null
    }

    try {
      // Create a new Date object from the date string
      const localDate = new Date(dateString);

      // Convert to UTC using the timezone offset
      const utcDate = new Date(
        localDate.getTime() + localDate.getTimezoneOffset() * 60_000,
      );

      // Format to ISO string
      return utcDate.toISOString();
    } catch (error) {
      this.customLogger.error(
        `Error converting date to UTC: ${error.message}`,
        context,
      );
      return undefined;
    }
  }
}

