  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: PlantConfigService.name,
      userId,
    };
  }

  private readonly lastStoredPlantPayload: Map<number, PlantConfig>;

  private readonly maxCacheSize = 10_000;

  public constructor(
    @InjectRepository(PlantConfig)
    private readonly plantConfigRepository: Repository<PlantConfig>,
    private readonly customLogger: AppLogger,
  ) {
    this.lastStoredPlantPayload = new Map();
  }

  private async upsertPayload(payload: PlantConfig): Promise<void> {
    const context = PlantConfigService.createLogContext(
      'upsertPayload',
      payload?.plant,
    );
    if (!payload) {
      this.customLogger.error(`Payload is empty ${payload}`, context);
      return;
    }
    const { plant, ...plantConfigData } = payload;

    if (plant === null || plant === undefined) {
      this.customLogger.error('Invalid payload: missing plant', context);
      return;
    }

    // Deduplicate: skip DB write if payload is identical to the last stored one
    const lastPayload = this.lastStoredPlantPayload.get(plant);
    if (
      lastPayload &&
      JSON.stringify(lastPayload) === JSON.stringify(payload)
    ) {
      this.customLogger.debug(
        `Skipping upsert for plant ${plant} as the payload is identical to the last stored one`,
        context,
      );
      return;
    }

    const startTime = Date.now();
    try {
      await this.plantConfigRepository.upsert(
        {
          plant,
          ...plantConfigData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plant'] },
      );
      // Evict oldest entry if cache exceeds max size (FIFO)
      if (this.lastStoredPlantPayload.size >= this.maxCacheSize) {
        const firstKey = this.lastStoredPlantPayload.keys().next()?.value;
        if (firstKey !== undefined) {
          this.lastStoredPlantPayload.delete(firstKey);
        }
      }
      this.lastStoredPlantPayload.set(plant, payload);
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'plant-config',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'plant-config',
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting plantConfig: ${error.message}`,
        context,
      );
    }
  }

  @OnEvent('plantConfig.c')
  private async create(payload: PlantConfig): Promise<void> {
    await this.upsertPayload(payload);
  }

  @OnEvent('plantConfig.u')
  private async updateByPlantConfig(payload: PlantConfig): Promise<void> {
    await this.upsertPayload(payload);
  }

  @OnEvent('plantConfig.r')
  private async readSnapshot(payload: PlantConfig): Promise<void> {
    await this.upsertPayload(payload);
  }
}

