  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { TpaAssignementMessage } from '@/common/publish-message/interface/publish-tpa-assignement.interface';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { TpaAssignment } from '@/modules/tpa-assignment/tpa-assignment.entity';
import { TpaCode } from '@/modules/tpa-code/tpa-code.entity';

@Injectable()
export class TpaAssignmentService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: TpaAssignmentService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(TpaAssignment)
    private readonly tpaAssignmentRepository: Repository<TpaAssignment>,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
    private readonly customLogger: AppLogger,
    @InjectRepository(TpaCode)
    private readonly tpaCodeRepository: Repository<TpaCode>,
  ) {}

  @OnEvent('tpaAssignment.c')
  private async create(payload: TpaAssignment): Promise<void> {
    const context = TpaAssignmentService.createLogContext(
      'create',
      payload?.plant,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const startTime = Date.now();
    try {
      const { ...tpaAssignmentData } = payload;
      const { tpaId, plant } = payload;

      // Find the TpaCode entity based on miiTpaId and plant
      const tpaCodeToFind = await this.tpaCodeRepository.findOne({
        where: { plant, tpaId },
      });
      if (tpaCodeToFind) {
        const newTpaAssignmentData = {
          ...tpaAssignmentData,
          tpaCode: tpaCodeToFind.tpaCode, // Use the found TpaCode entity directly
        };
        await this.tpaAssignmentRepository.upsert(
          { ...newTpaAssignmentData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
          { conflictPaths: ['assignId', 'plant'] },
        );
        const sqlDuration = Date.now() - startTime;
        const tpaAssignmentMessage: TpaAssignementMessage = {
          assignId: newTpaAssignmentData.assignId,
          plant,
        };

        await this.publishMessageService.publishMessage(
          this.eventhubService.topicTpaAssignement,
          tpaAssignmentMessage,
        );

        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          String(plant),
          'tpa-assignment',
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.SQL,
          String(plant),
          'tpa-assignment',
        );
      } else {
        this.customLogger.error(
          'TpaCode not found for the given miiTpaId and plant.',
          context,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error in inserting into the database: ${error.message}`,
        context,
      );
    }

    return undefined;
  }

  @OnEvent('tpaAssignment.u')
  private async updateTpaAssignment(payload: TpaAssignment): Promise<void> {
    const context = TpaAssignmentService.createLogContext(
      'updateTpaAssignment',
      payload?.plant,
    );
    if (!payload) {
      this.customLogger.error(`payload is empty`, context);
      return;
    }

    const { tpaId, plant } = payload;
    const { ...tpaAssignmentData } = payload;

    const startTime = Date.now();
    try {
      // Find the TpaCode entity based on tpaId and plant
      const tpaCodeToFind = await this.tpaCodeRepository.findOne({
        where: { plant, tpaId },
      });

      if (!tpaCodeToFind) {
        return;
      }

      const newTpaAssignmentData = {
        ...tpaAssignmentData,
        tpaCode: tpaCodeToFind.tpaCode, // Use the found TpaCode entity directly
      };

      await this.tpaAssignmentRepository.upsert(
        {
          ...newTpaAssignmentData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['assignId', 'plant'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'tpa-assignment',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'tpa-assignment',
      );
      const tpaAssignmentMessage: TpaAssignementMessage = {
        assignId: newTpaAssignmentData.assignId,
        plant: Number(newTpaAssignmentData.plant),
      };

      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTpaAssignement,
        tpaAssignmentMessage,
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Tpa Assignment: ${error.message}`,
        context,
      );
    }
  }

  @OnEvent('tpaAssignment.r')
  private async readSnapshot(payload: TpaAssignment): Promise<void> {
    const context = TpaAssignmentService.createLogContext(
      'readSnapshot',
      payload?.plant,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const { tpaId, plant, ...tpaAssignmentData } = payload;

    const startTime = Date.now();
    try {
      // Find the TpaCode entity based on miiTpaId and plant
      const tpaCodeToFind = await this.tpaCodeRepository.findOne({
        where: { plant, tpaId },
      });

      if (!tpaCodeToFind) {
        return this.customLogger.error(
          'TpaCode not found for the given miiTpaId and plant.',
          context,
        );
      }

      const newTpaAssignmentData = {
        plant,
        tpaId,
        ...tpaAssignmentData,
        tpaCode: tpaCodeToFind.tpaCode, // Use the found TpaCode entity directly
      };

      await this.tpaAssignmentRepository.upsert(
        {
          ...newTpaAssignmentData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['assignId', 'plant'] },
      );

      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'tpa-assignment',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'tpa-assignment',
      );

      const tpaAssignmentMessage: TpaAssignementMessage = {
        assignId: newTpaAssignmentData.assignId,
        plant: Number(newTpaAssignmentData.plant),
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTpaAssignement,
        tpaAssignmentMessage,
      );
    } catch (error) {
      this.customLogger.error(
        `Error Upserting TpaAssignments with ID ${tpaId} and plant ${plant}: ${error.message}`,
        context,
        error.stack,
      );
    }

    return undefined;
  }
}

