    "no-eval": "error",
    "no-extra-bind": "error",
    "no-invalid-this": "off",
    "no-new-func": "error",
    "no-new-wrappers": "error",
    "no-param-reassign": "error",
    "no-restricted-imports": [
      "error",
      {
        "paths": [
          "rxjs/Rx"
        ],
        "patterns": [
          "rxjs/internal/*"
        ]
      }
    ],
    "no-restricted-syntax": [
      "error",
      "ForInStatement"
    ],
    "no-shadow":"off",
    "no-template-curly-in-string": "error",
    "no-throw-literal": "error",
    "no-undef-init": "error",
    "no-underscore-dangle": [
      "error",
      {
        "allowAfterThis": true
      }
    ],
    "no-useless-constructor": "off",
    "no-var": "error",
    "no-void": "error",
    "one-var": [
      "error",
      "never"
    ],
    "prefer-const": "error",
    "prefer-object-spread": "error",
    "prefer-template": "error",
    "radix": "error",
    "sort-class-members/sort-class-members": [
      2,
      {
        "accessorPairPositioning": "getThenSet",
        "order": [
          "[static-properties]",
          "[static-methods]",
          "[properties]",
          "[conventional-private-properties]",
          "constructor",
          "[methods]",
          "[conventional-private-methods]"
        ]
      }
    ],
    "sort-keys": [
      "error",
      "asc",
      {
        "caseSensitive": true,
        "minKeys": 2,
        "natural": true
      }
    ],
    "sort-vars": "error",
    "yoda": "error"
  },
  "overrides": [
  {
    "files": [ "*.ts" ],
    "rules": {
      "sort-keys": [
        "error",
        "asc", {
          "minKeys": 5,
          "allowLineSeparatedGroups": true  
        }
      ]
    }
  },
  {
    "files": [ "src/**/*.dto.ts" ],
    "rules": {
      "@typescript-eslint/naming-convention": "off",
      "no-underscore-dangle": "off",
      "camelcase": "off",
      "no-undef": "warn"
    }
  },
  {
    "files": [
      "src/**/*.service.ts",
      "src/**/*.service.spec.ts"
    ],
    "rules": {
      "unicorn/no-null": "off"
    }
  },
  {
    "files": [ "src/main.ts" ],
    "rules": {
      "unicorn/prefer-top-level-await": "off"
    }
  }]
